import{z as o,x as n,o as A,c as p,q as B,j as i,D as E,d as r,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"API 安全与 BOLA","description":"","frontmatter":{"title":"API 安全与 BOLA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/api-security-bola.md","filePath":"cs/api-security-bola.md","lastUpdated":1791063341000}'),d={name:"cs/api-security-bola.md"};function D(c,a,S,h,m,F){const t=n("Mermaid");return A(),p("div",null,[a[2]||(a[2]=B('<h1 id="api-安全与-bola" tabindex="-1">API 安全与 BOLA <a class="header-anchor" href="#api-安全与-bola" aria-label="Permalink to &quot;API 安全与 BOLA&quot;">​</a></h1><div class="epigraph"><p>对象级授权失败：认证过了，但改一个标识就碰到别人的资源。API 把客体直接暴露成 URL 与 JSON，授权必须每对象检查，而不是只检查已登录。</p><footer>—— 据 OWASP API Security；CWE-639 IDOR；对照[最小特权](/cs/acl-least-priv)</footer></div><p>上一课<a href="/cs/waf">WAF</a>收尾时说它几乎不管「这个对象标识是不是你的」；缺口正是 <strong>BOLA 与 IDOR</strong>。Web 课序在此收口，下一课序转向网络防御。不给盗数据步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>REST 把对象直接暴露成 URL 与 JSON：/orders/4821 里那个数字就是客体标识。漏洞形态是服务器验了会话（你是合法用户）却没验属主（这单是不是你的），改一个数字就碰到别人的资源。缺口是每请求的属主或能力检查——在数据访问层按属主过滤，而不是在路由层验完登录就放行；批量接口与导出功能更容易漏。</p><p><span class="marginnote">数字实例：订单号若是自增整数，攻击者把 URL 里的 4821 换成 4822、4823 逐个试，一晚就能遍历全站订单。UUID 把猜测代价升到天文数字，但标识一旦从邮件或分享链接里泄露，这层防护立刻归零——它只是减速带，不是门锁。</span></p><h3 id="查询语言接口" tabindex="-1">查询语言接口 <a class="header-anchor" href="#查询语言接口" aria-label="Permalink to &quot;查询语言接口&quot;">​</a></h3><p>GraphQL 这类查询语言接口同理：每个节点与字段同样要授权，内省（introspection）只告诉你 schema 长什么样，不是读数据的许可。</p><p><span class="marginnote">术语翻译：内省就像餐厅把完整菜单印给你看——你知道后厨能做什么菜，但能不能上桌仍要一桌一桌核资格。漏扫工具常靠内省枚举字段，看到的只是菜单；每字段照常鉴权，菜单公开也不碍事。</span></p><p><span class="marginnote">OWASP API1。禁止 IDOR 利用教程。IDS 下一课换到网络流量视角。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法分两侧。测试侧：对每个取对象的端点换标识、换租户重放，确认 403 而非 200。设计侧：把属主检查压进数据访问层——查询自带「属主 = 当前主体」过滤，或改用与用户绑定的能力令牌。不可预测的标识（UUID）只提高枚举代价，不是授权：标识一旦经邮件、协作功能泄漏，这条防线即无。下一课 IDS/IPS。</p>',13)),(A(),i(s,null,{default:E(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUTH%5B%22%E5%B7%B2%E8%AE%A4%E8%AF%81%22%5D%20--%3E%20OBJ%5B%22%E5%AE%A2%E4%BD%93%E6%A0%87%E8%AF%86%22%5D%0A%20%20OBJ%20--%3E%20AUTHZ%5B%22%E5%B1%9E%E4%B8%BB%E6%88%96%20ACL%20%E6%A3%80%E6%9F%A5%22%5D%0A%20%20AUTHZ%20--%3E%20FAIL%5B%22%E5%8F%AA%E9%AA%8C%E7%99%BB%E5%BD%95%E5%88%99%20BOLA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制上是整个 Web 单元的收口：从 XSS 的注入执行、CSRF 的请求伪造到 BOLA 的客体越权，共同教训是「每层信任判定要有独立证据」——认证的证据不能挪用为授权的证据。下一课序从流量检测起步，前提是假定应用仍会漏：BOLA 不留注入特征，常规 WAF 与漏扫看不见，这正是纵深需要检测层的原因。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「登录了接口就安全」。实际上认证回答「你是谁」，授权回答「这个对象归不归你」，两问必须各自取证——把前者的答案挪去顶替后者，就是 BOLA 的全部成因。")],-1)),(A(),i(s,null,{default:E(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%20GET%20%2Forders%2F4821%22%5D%20--%3E%20SES%5B%22%E4%BC%9A%E8%AF%9D%E6%9C%89%E6%95%88%3F%22%5D%0A%20%20SES%20--%3E%7C%E6%98%AF%7C%20Q%5B%22%E8%BF%9B%E5%85%A5%E6%95%B0%E6%8D%AE%E8%AE%BF%E9%97%AE%E5%B1%82%22%5D%0A%20%20Q%20--%3E%20F%7B%22%E6%9F%A5%E8%AF%A2%E8%87%AA%E5%B8%A6%E5%B1%9E%E4%B8%BB%E8%BF%87%E6%BB%A4%3F%22%7D%0A%20%20F%20--%3E%7C%E5%B8%A6%E8%BF%87%E6%BB%A4%7C%20SAFE%5B%22%E5%8F%AA%E8%BF%94%E5%9B%9E%20owner%20%3D%20%E5%BD%93%E5%89%8D%E4%B8%BB%E4%BD%93%E7%9A%84%E8%A1%8C%22%5D%0A%20%20F%20--%3E%7C%E4%B8%8D%E5%B8%A6%7C%20LEAK%5B%22%E7%85%A7%E5%8D%95%E5%85%A8%E6%94%B6%2C%20%E8%BF%94%E5%9B%9E%E4%BB%BB%E6%84%8F%E7%BC%96%E5%8F%B7%E7%9A%84%E8%A1%8C%22%5D%0A%20%20SAFE%20--%3E%20R1%5B%224821%20%E5%BD%92%E4%BD%A0%3A%20200%22%5D%0A%20%20SAFE%20--%3E%20R2%5B%22%E4%B8%8D%E5%BD%92%E4%BD%A0%3A%20%E7%A9%BA%E7%BB%93%E6%9E%9C%E6%88%96%20403%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零盗取教程；边界要点名：对象级授权错误是逻辑缺陷——响应正常、属主错误，自动化工具覆盖差，测试要靠人按数据模型逐个走。下一课序 IDS/IPS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WAF 看不见对象属主。</li><li>BOLA：认证不等于对该客体的授权。</li><li>每对象检查；随机标识不是 ACL。</li><li>下一课序：IDS/IPS。</li><li>出处：OWASP API Security；CWE-639。</li></ul>',4))])}const f=o(d,[["render",D]]);export{P as __pageData,f as default};
